for a in mol.GetAtoms():
    if a.GetSymbol()=="H": Hof.setdefault(a.GetNeighbors()[0].GetIdx(), []).append(a.GetIdx())
for i in list(fragC): fragC += Hof.get(i, [])
em = Chem.RWMol(); mp={}
for i in fragC:
    a=mol.GetAtomWithIdx(i); na=Chem.Atom(a.GetSymbol()); na.SetNoImplicit(True); na.SetNumExplicitHs(0)
    mp[i]=em.AddAtom(na)
for b in mol.GetBonds():
    i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx()
    if i in mp and j in mp: em.AddBond(mp[i],mp[j],b.GetBondType())
m=em.GetMol()
Chem.SanitizeMol(m, Chem.SanitizeFlags.SANITIZE_ALL ^ Chem.SanitizeFlags.SANITIZE_PROPERTIES)
print("fragC atoms:", m.GetNumAtoms())
for seed in (11, 21, 31, 41):
    ps=AllChem.ETKDGv3(); ps.randomSeed=seed; ps.maxIterations=500
    r=AllChem.EmbedMolecule(m,ps)
