    for b in m.GetBonds():
        i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx(); adj[i,j]=adj[j,i]=True
    adj2=adj@adj
    for i in range(len(P)):
        for j in range(i+1,len(P)):
