names=json.load(open("idx.json"))
def sign_of(fn):
    lines=[l.split() for l in open(fn).readlines()[2:] if l.strip()]
    els=[l[0] for l in lines]; P=np.array([[float(x) for x in l[1:4]] for l in lines])
    i=names["Cst"]; dd={}
    for j in range(len(P)):
        if els[j]=="H" and np.linalg.norm(P[j]-P[i])<1.3: dd["H"]=P[j]-P[i]
    dd["Ca"]=P[names["Ca"]]-P[i]; dd["Ch"]=P[names["Ch"]]-P[i]; dd["N"]=P[names["N"]]-P[i]
    return np.sign(np.dot(np.cross(dd["Ca"],dd["Ch"]),dd["N"])), len(dd)
for f in ("assembled.xyz","pre_xtb.xyz","xtb_opt.xyz"):
