import numpy as np, json, itertools
from rdkit import Chem
names=json.load(open("idx.json"))
mol=Chem.MolFromMolFile("molH.mol", removeHs=False, sanitize=False)
nat=mol.GetNumAtoms()
lines=[l.split() for l in open("pre_xtb.xyz").readlines()[2:] if l.strip()]
els=[l[0] for l in lines]; P=np.array([[float(x) for x in l[1:4]] for l in lines])
def subtree(root, block):
    seen={root}; stack=[root]
    while stack:
        x=stack.pop()
        for nb in mol.GetAtomWithIdx(x).GetNeighbors():
            y=nb.GetIdx()
            if y not in seen and y!=block: seen.add(y); stack.append(y)
    return seen
sets = {
 "tet":  subtree(names["Cst"], names["N"]),      # tetralin + Cst-H, about N-Cst
 "troc": subtree(names["Ctroc"], names["N"]),    # Troc about N-Ctroc
 "tbu":  subtree(names["Cq"], names["Cco"]),
 "ccl3": subtree(names["Ctrocc"], names["Oest"]),
 "ph":   subtree(names["P1"], names["C1"]),
}
axes = {"tet":(names["N"],names["Cst"]), "troc":(names["N"],names["Ctroc"]),
        "tbu":(names["Cco"],names["Cq"]), "ccl3":(names["Oest"],names["Ctrocc"]),
        "ph":(names["C1"],names["P1"])}
def rot_about(Pm, idxset, a, b, ang):
    Pm=Pm.copy(); ax=Pm[b]-Pm[a]; ax/=np.linalg.norm(ax)
    c,s=np.cos(ang),np.sin(ang)
    K=np.array([[0,-ax[2],ax[1]],[ax[2],0,-ax[0]],[-ax[1],ax[0],0]])
    Rr=np.eye(3)*c+s*K+(1-c)*np.outer(ax,ax)
    for i in idxset: Pm[i]=(Rr@(Pm[i]-Pm[a]))+Pm[a]
    return Pm
adj=np.zeros((nat,nat),bool)
for b in mol.GetBonds():
    i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx(); adj[i,j]=adj[j,i]=True
adj2=adj@adj; skip=adj|adj2|np.eye(nat,dtype=bool)
ii,jj=np.triu_indices(nat,1); keep=~skip[ii,jj]; II,JJ=ii[keep],jj[keep]
sym=np.array(els)
lim=np.where((sym[II]=="H")|(sym[JJ]=="H"),2.1,2.5)
def clash(Pm):
    d=np.linalg.norm(Pm[II]-Pm[JJ],axis=1)
    return np.sum(np.clip(lim-d,0,None)**2)
def apply(angs):
    Pm=P
    for k in ("tet","troc","tbu","ccl3","ph"):
        Pm=rot_about(Pm, sets[k], *axes[k], np.radians(angs[k]))
    return Pm
keys=list(sets.keys())
best=None
import random
random.seed(0)
# coarse grid over tet & troc (main strain), then coordinate descent over all
for a1 in range(0,360,30):
    for a2 in range(0,360,30):
        angs={"tet":a1,"troc":a2,"tbu":0,"ccl3":0,"ph":0}
        s=clash(apply(angs))
        if best is None or s<best[0]: best=(s,dict(angs))
for it in range(4):
    for k in keys:
        for da in range(0,360,15):
            trial=dict(best[1]); trial[k]=da
            s=clash(apply(trial))
            if s<best[0]: best=(s,trial)
print("best clash:", round(best[0],3), best[1])
Pm=apply(best[1])
bad=[]
for a,b in itertools.combinations(range(nat),2):
    if skip[a,b]: continue
    dd=np.linalg.norm(Pm[a]-Pm[b])
    if dd<2.0: bad.append((a,b,sym[a],sym[b],round(dd,2)))
print("contacts<2.0:", bad)
i=names["Cst"]; dd2={}
for j in range(nat):
    if els[j]=="H" and np.linalg.norm(Pm[j]-Pm[i])<1.3: dd2["H"]=Pm[j]-Pm[i]
dd2["Ca"]=Pm[names["Ca"]]-Pm[i]; dd2["Ch"]=Pm[names["Ch"]]-Pm[i]; dd2["N"]=Pm[names["N"]]-Pm[i]
sgn=np.sign(np.dot(np.cross(dd2["Ca"],dd2["Ch"]),dd2["N"]))
print("stereo sign:", sgn, "(must be -1)")
assert sgn==-1
with open("pre_xtb4.xyz","w") as f:
    f.write(f"{nat}\npre-xTB4 cation\n")
    for e,p in zip(els,Pm): f.write(f"{e} {p[0]:.6f} {p[1]:.6f} {p[2]:.6f}\n")
print("wrote pre_xtb4.xyz")
